command:
cd /app && awk '
FNR==1 {
  f=FILENAME; sub(/.*\//,"",f); d=substr(f,1,10);
  t=(d=="2025-08-12"); d7=(d>="2025-08-06" && d<="2025-08-12");
  d30=(d>="2025-07-14" && d<="2025-08-12"); mtd=(d>="2025-08-01" && d<="2025-08-12");
}
{
  s=$3;
  if (s=="[ERROR]") k="ERROR"; else if (s=="[WARNING]") k="WARNING"; else if (s=="[INFO]") k="INFO"; else next;
  TOT[k]++;
  if (t) TODAY[k]++;
  if (d7) D7[k]++;
  if (d30) D30[k]++;
  if (mtd) MTD[k]++;
}
END {
  split("ERROR WARNING INFO", S, " ");
  print "period,severity,count";
  for(i=1;i<=3;i++) print "today," S[i] "," TODAY[S[i]]+0;
  for(i=1;i<=3;i++) print "last_7_days," S[i] "," D7[S[i]]+0;
  for(i=1;i<=3;i++) print "last_30_days," S[i] "," D30[S[i]]+0;
  for(i=1;i<=3;i++) print "month_to_date," S[i] "," MTD[S[i]]+0;
  for(i=1;i<=3;i++) print "total," S[i] "," TOT[S[i]]+0;
}' logs/*.log > /tmp/expected.csv
echo "--- diff (empty = match) ---"; diff /tmp/expected.csv summary.csv && echo "MATCH"
echo "--- boundary file spot checks ---"
echo -n "2025-08-06 files: "; grep -c . <(ls logs/2025-08-06_*.log)
echo -n "2025-07-14 files: "; grep -c . <(ls logs/2025-07-14_*.log)
echo -n "2025-07-13 files (should be excluded from last_30_days): "; ls logs/2025-07-13_*.log | wc -l
echo "--- pre-August-DEBUG-free line count sanity ---"
awk 'END{print "total_lines="NR}' logs/*.log
